using System.Collections;
using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

public class PurifyMinimunWaveAction : PurifyMinimunWaveBaseAction
{
	[Header("PurifyMinimunWave")]
	[SerializeField]
	private bool purifyAfterMinimunWaveAction;

	[Header("VFX")]
	[SerializeField]
	private bool enableVFXDelay;

	[SerializeField]
	[ShowIf("enableVFXDelay")]
	private float vfxDelay;

	public override void CastTargetAmount(GameObject target, int purifyAmount, GameObject source)
	{
		if (ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled() && enableVFXDelay)
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(CastTargetAmountVFXDelay(target, purifyAmount, source));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
			return;
		}
		if (purifyAfterMinimunWaveAction)
		{
			TryTriggeringMinimumWaveAction(target, source);
		}
		SpawnVFX(GetVFXOwnerPosition(target), 3f);
		if (IsVFXEnabled())
		{
			PlaySFX();
		}
		purifyAction.CastTargetAmount(target, purifyAmount, source);
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
		if (!purifyAfterMinimunWaveAction)
		{
			TryTriggeringMinimumWaveAction(target, source);
		}
	}

	private IEnumerator CastTargetAmountVFXDelay(GameObject target, int amount, GameObject source)
	{
		SpawnVFX(GetVFXOwnerPosition(target), 3f);
		if (IsVFXEnabled())
		{
			PlaySFX();
		}
		yield return new WaitForSeconds(vfxDelay);
		if (purifyAfterMinimunWaveAction)
		{
			TryTriggeringMinimumWaveAction(target, source);
		}
		purifyAction.CastTargetAmount(target, amount, source);
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
		if (!purifyAfterMinimunWaveAction)
		{
			TryTriggeringMinimumWaveAction(target, source);
		}
	}

	private void TryTriggeringMinimumWaveAction(GameObject target, GameObject source)
	{
		UnitEffects component = target.GetComponent<UnitEffects>();
		if (component.IsEffectActiveGetAmount(waveEffect, activateFeedback: false) >= minimunWaveAmount)
		{
			MinimunWaveAction(source);
			if (waveCost > 0)
			{
				component.IsEffectActiveAndDecreaseEffect(waveEffect, waveCost);
			}
		}
		else
		{
			ApplyWave(target);
		}
	}

	public virtual void MinimunWaveAction(GameObject source)
	{
	}
}
